text:
  border-block: 1px solid transparent;
  align-items: center;
}

richlistitem:is([is="chat-imconv-richlistitem"], [is="chat-contact-richlistitem"], [is="chat-group-richlistitem"]) {
  pointer-events: auto;
}

richlistitem:is([is="chat-imconv-richlistitem"], [is="chat-contact-richlistitem"], [is="chat-group-richlistitem"]):not([selected]):hover {
  background-color: rgba(0, 0, 0, 0.1);
}

:root[lwt-tree] richlistitem[is="chat-group-richlistitem"],
:root[lwt-tree] richlistitem[is="chat-imconv-richlistitem"]:not([selected]),
:root[lwt-tree] richlistitem[is="chat-contact-richlistitem"]:not([selected]) {
  color: var(--sidebar-color);
}

richlistitem[is="chat-imconv-richlistitem"][selected],
richlistitem[is="chat-contact-richlistitem"][selected] {
  background-color: var(--imbox-selected-background-color) !important;
  border-color: var(--sidebar-border) !important;
  color: var(--imbox-selected-text-color) !important;
}

:root[lwt-tree] richlistitem[is="chat-group-richlistitem"][selected],
:root[lwt-tree] richlistitem:is([is="chat-imconv-richlistitem"], [is="chat-contact-richlistitem"], [is="chat-group-richlistitem"]):not([selected]):hover {
  background-color: var(--sidebar-highlight-background-color, hsla(0, 0%, 80%, 0.3));
  color: var(--sidebar-highlight-text-color, var(--sidebar-color));
}

:root[lwt-tree-brighttext] richlistitem[is="chat-group-richlistitem"][selected],
:root[lwt-tree-brighttext]
  richlistitem:is([is="chat-imconv-richlistitem"], [is="chat-contact-richlistitem"], [is="chat-group-richlistitem"]):not([selected]):hover {
  background-color: var(--sidebar-highlight-background-color, rgba(249, 249, 250, 0.1));
}
